BRAND_CSS = r'''
.brand-logo-wrap{
  display:block;
  width:min(760px,82vw);
  max-width:100%;
  margin:0 auto;
}
.brand-logo-wrap svg{
  display:block;
  width:100%;
  height:auto;
  filter:drop-shadow(0 10px 22px rgba(16,32,21,.16));
}
@media(max-width:900px){
  .brand-logo-wrap{width:min(620px,88vw);}
}
'''


def apply_challenge_ui_branding_patch() -> None:
    """Apply final submission branding/copy to the full-data judge UI.

    Kept as a wrapper so the final polish does not alter route policy, provider
    selection, data access, execution, or verification behavior.
    """

    from app import challenge_ui as _challenge_ui

    original = _challenge_ui.render_challenge_ui
    if getattr(original, "_proof_of_one_branding_patch", False):
        return

    def branded_render_challenge_ui(*, llm_connected: bool) -> str:
        html = original(llm_connected=llm_connected)
        html = html.replace(
            "</style>",
            f"{BRAND_CSS}\n</style>",
            1,
        )
        html = html.replace(
            "<h1>Proof of One</h1>",
            f"<div class=\"brand-logo-wrap\" aria-label=\"Proof of One\">{PROOF_OF_ONE_LOGO_SVG}</div>",
            1,
        )
        html = html.replace(
            ">Set route · send<",
            ">Send message<",
            1,
        )
        return html

    setattr(branded_render_challenge_ui, "_proof_of_one_branding_patch", True)
    _challenge_ui.render_challenge_ui = branded_render_challenge_ui  # type: ignore[assignment]
